      "react": "import { useState } from \"react\";\nimport { Checkbox } from \"@chumlab/ui/checkbox\";\n\nexport default function CheckboxExample() {\n  const [focusLog, setFocusLog] = useState<string[]>([]);\n  return (\n    <>\n      <Checkbox\n        label=\"Focus me and check the log\"\n        size=\"md\"\n        shape=\"rounded\"\n        classes={\n          {\n            root: \"\",\n            label: \"text-sm font-medium text-cl-text\",\n            description: \"text-xs text-cl-text-secondary\"\n          }\n        }\n        onFocus={\n          () =>\n          setFocusLog((prev) => [\"Focused\", ...prev.slice(0, 4)])\n        }\n        onBlur={\n          () =>\n          setFocusLog((prev) => [\"Blurred\", ...prev.slice(0, 4)])\n        }\n      />\n      {\n        focusLog.length > 0 && (\n          <div className=\"mt-3 text-xs font-mono space-y-1 text-cl-text-secondary\">\n            {\n              focusLog.map((log, i) => (\n                <div key={i}>\n                  {log}\n                </div>\n              ))\n            }\n          </div>\n        )\n      }\n    </>\n  );\n}\n",
      "next": "\"use client\";\n\nimport { useState } from \"react\";\nimport { Checkbox } from \"@chumlab/ui/checkbox\";\n\nexport default function CheckboxExample() {\n  const [focusLog, setFocusLog] = useState<string[]>([]);\n  return (\n    <>\n      <Checkbox\n        label=\"Focus me and check the log\"\n        size=\"md\"\n        shape=\"rounded\"\n        classes={\n          {\n            root: \"\",\n            label: \"text-sm font-medium text-cl-text\",\n            description: \"text-xs text-cl-text-secondary\"\n          }\n        }\n        onFocus={\n          () =>\n          setFocusLog((prev) => [\"Focused\", ...prev.slice(0, 4)])\n        }\n        onBlur={\n          () =>\n          setFocusLog((prev) => [\"Blurred\", ...prev.slice(0, 4)])\n        }\n      />\n      {\n        focusLog.length > 0 && (\n          <div className=\"mt-3 text-xs font-mono space-y-1 text-cl-text-secondary\">\n            {\n              focusLog.map((log, i) => (\n                <div key={i}>\n                  {log}\n                </div>\n              ))\n            }\n          </div>\n        )\n      }\n    </>\n  );\n}\n",
      "needsClientBoundary": true
